<script setup lang="ts">
import { Activity, BarChart3, GraduationCap, TrendingDown } from '@lucide/vue'
import { onMounted, ref } from 'vue'
import api from '../api'
import { useLocaleStore } from '../stores/locale'
const locale=useLocaleStore();const loading=ref(true);const error=ref('');const report=ref<any>({summary:{},exam_stats:[],subject_stats:[],at_risk:[]});const name=(value:any)=>locale.locale==='ar'?(value?.name_ar||value?.name_en):(value?.name_en||value?.name_ar);const reasons=(items:string[])=>items.map(item=>locale.tr(item)).join(' · ');const barWidth=(value:number)=>({width:`${Math.min(value,100)}%`});async function load(){try{report.value=(await api.get('/examinations/performance')).data}catch(e:any){error.value=e.response?.data?.message||'Unable to load performance insights.'}finally{loading.value=false}}onMounted(load)
</script>
<template><div class="app-shell teacher-shell performance-workspace"><main class="dashboard-main"><header><div class="global-search"><BarChart3/><span>{{locale.tr('Performance insights')}}</span></div></header><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading performance insights…')}}</div><div v-else class="dashboard-content teacher-content"><div class="teacher-page-head"><div><span>{{locale.tr('EARLY SUPPORT')}}</span><h1>{{locale.tr('Performance')}}</h1><p>{{locale.tr('Spot progress trends and follow up with students who need support.')}}</p></div></div><div v-if="error" class="form-error">{{error}}</div><section class="teacher-stats performance-stats"><article><span><BarChart3/></span><small>{{locale.tr('CLASS AVERAGE')}}</small><b>{{report.summary.class_average||0}}%</b><em>{{report.summary.published_exams||0}} {{locale.tr('published exams')}}</em></article><article><span><GraduationCap/></span><small>{{locale.tr('PUBLISHED RESULTS')}}</small><b>{{report.summary.published_exams||0}}</b><em>{{locale.tr('ready for families')}}</em></article><article><span><Activity/></span><small>{{locale.tr('NEEDS SUPPORT')}}</small><b>{{report.summary.students_at_risk||0}}</b><em>{{locale.tr('early warning students')}}</em></article></section><section class="performance-grid"><article class="teacher-card"><div class="teacher-card-head"><div><small>{{locale.tr('EXAM TRENDS')}}</small><h2>{{locale.tr('Assessment averages')}}</h2></div><TrendingDown/></div><div v-if="!report.exam_stats.length" class="teacher-empty compact"><BarChart3/><b>{{locale.tr('No published results yet.')}}</b></div><div v-else class="performance-list"><div v-for="exam in report.exam_stats" :key="exam.id" class="performance-row"><div><b>{{exam.title}}</b><small>{{exam.marks_count}} {{locale.tr('students marked')}}</small></div><strong>{{exam.average}}%</strong><span class="performance-bar"><i :style="barWidth(exam.average)"></i></span></div></div></article><article class="teacher-card"><div class="teacher-card-head"><div><small>{{locale.tr('SUBJECT TRENDS')}}</small><h2>{{locale.tr('Subject averages')}}</h2></div><BarChart3/></div><div v-if="!report.subject_stats.length" class="teacher-empty compact"><BarChart3/><b>{{locale.tr('No published results yet.')}}</b></div><div v-else class="performance-list"><div v-for="item in report.subject_stats" :key="item.id" class="performance-row"><div><b>{{name(item.subject)}}</b><small>{{item.marks_count}} {{locale.tr('marks recorded')}}</small></div><strong>{{item.average}}%</strong><span class="performance-bar"><i :style="barWidth(item.average)"></i></span></div></div></article><article class="teacher-card"><div class="teacher-card-head"><div><small>{{locale.tr('EARLY WARNINGS')}}</small><h2>{{locale.tr('Follow up list')}}</h2></div><Activity/></div><div v-if="!report.at_risk.length" class="teacher-empty compact"><Activity/><b>{{locale.tr('No students need support yet')}}</b></div><div v-else class="performance-list"><div v-for="item in report.at_risk" :key="item.student.student_code" class="performance-row risk"><div><b>{{name(item.student)}}</b><small>{{item.student.student_code}} · {{reasons(item.reasons)}}</small></div><strong><TrendingDown/></strong></div></div></article></section></div></main></div></template>
